81	// tc_train_step: one Fork-B TC step. params [total] fp32 (updated in place);
82	// tokens [B,kSeq] int32; targets [B] int32; state [3*total] fp32 ([m|v|extra]).
83	// Returns {loss (cpu float scalar tensor), grad [total] fp32 (the reduced grad)}.
84	static std::vector<torch::Tensor> tc_train_step(
85	        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
86	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
87	        double weight_decay, double bc1, double bc2, int64_t step,
88	        int64_t ncta_cap) {
89	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
90	    TORCH_CHECK(params.numel() == kDecTotalElems, "params must be the flat decoder blob (", kDecTotalElems, ")");
91	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
92	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
93	    const int B = (int)targets.numel();
94	    TORCH_CHECK(tokens.numel() == (int64_t)B * dec::kSeq, "tokens must be [B,kSeq]");
95	    TORCH_CHECK((B % 16) == 0, "TC path requires B %% 16 == 0 (dW K-loop is 16-step atoms)");
96	    const int64_t total = kDecTotalElems;
97	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
98	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
99	
100	    const int nCTA = tc_effective_nctas(params, (int)ncta_cap);
101	    TcScratch& sc = tc_scratch_for(params, B, nCTA);
102	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
103	    auto loss_dev = torch::zeros({1}, torch::dtype(torch::kFloat32).device(params.device()));
104	
105	    PersistentContext ctx{
106	        sc.g_next.data_ptr<int>(),
107	        reinterpret_cast<unsigned*>(sc.g_arrived.data_ptr<int>()),
108	        reinterpret_cast<unsigned*>(sc.g_generation.data_ptr<int>()),
109	        ::sg::fused::sm90::kDecNumTensors,
110	        0u};
111	
112	    FusedOptState st;
113	    float* m = state.data_ptr<float>();
114	    st.exp_avg = m;
115	    st.exp_avg_sq = m + total;
116	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
117	    st.eps = (float)eps; st.wd = (float)weight_decay;
118	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
119	
120	    DecoderTokenCtx tok;
121	    tok.tokens = tokens.data_ptr<int>();
122	    tok.targets = targets.data_ptr<int>();
123	    tok.B = B;
124	    tok.workspace = sc.workspace.data_ptr<float>();
125	    tok.loss_out = loss_dev.data_ptr<float>();
126	
127	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
128	    cudaError_t err = ::sg::fused::sm90::launch_fused_decoder_megakernel_tc<OptId::AdamW>(
129	        ctx, params.data_ptr<float>(), tok, grad.data_ptr<float>(),
130	        (float)lr, (int)step, st, stream, nCTA);
131	    TORCH_CHECK(err == cudaSuccess, "TC megakernel launch failed: ", cudaGetErrorString(err));
132	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
133	
134	    return {loss_dev.to(torch::kCPU), grad};
135	}
