175	// scalar_train_step: the SAME (decoder × AdamW) cell run through the SCALAR
176	// default launcher (launch_fused_decoder_megakernel<AdamW>, which lives OUTSIDE
177	// the wgmma guard at fused_decoder_megakernel.cuh — so this wgmma-token TU
178	// can still call it). This exists ONLY so the step-time gate can time the live
179	// scalar path and the TC path BACK-TO-BACK in one process / one contention
180	// regime → an honest scalar:TC ratio. The scalar path uses its OWN workspace
181	// layout (nCTA*total grad partials + nCTA loss slots + 1 reduced loss), sized
182	// for nCTA = #SMs (the scalar launcher pins one CTA per SM, no cap). It is NOT
183	// the shipped invocation (that is dispatch.cpp via mega_decoder_real_adamw.cu);
184	// it is a measurement mirror. Returns {loss, reduced grad} like tc_train_step.
185	//
186	// GATED by SG_DEC_SCALAR_MEGAKERNEL: the legacy fp32 scalar megakernel does not
187	// fit smem at scaled SG_DEC_D (see the flag note in fused_decoder_megakernel.cuh).
188	// When OFF, this back-to-back timing mirror is compiled out (its only purpose is
189	// the scalar:TC ratio, which is moot when the scalar path is unavailable); the TC
190	// gates (tc_train_step) are unaffected.
191	#if SG_DEC_SCALAR_MEGAKERNEL
192	static std::vector<torch::Tensor> scalar_train_step(
193	        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
194	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
195	        double weight_decay, double bc1, double bc2, int64_t step) {
196	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
197	    TORCH_CHECK(params.numel() == kDecTotalElems, "params must be the flat decoder blob (", kDecTotalElems, ")");
198	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
199	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
200	    const int B = (int)targets.numel();
201	    TORCH_CHECK(tokens.numel() == (int64_t)B * dec::kSeq, "tokens must be [B,kSeq]");
202	    const int64_t total = kDecTotalElems;
203	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
204	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
205	
206	    int dev = params.get_device();
207	    int n_sms = 1;
208	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
209	
210	    // Separate cached scalar scratch (DO NOT reuse the TC workspace — different
211	    // layout/size; the TC one under-allocates the scalar nCTA*total partials).
212	    static torch::Tensor s_gn, s_ga, s_gg, s_ws;
213	    static int64_t s_ws_floats = 0;
214	    const int64_t need = (int64_t)n_sms * total + n_sms + 1;
215	    if (!s_gn.defined()) {
216	        auto oi = torch::dtype(torch::kInt32).device(params.device());
217	        s_gn = torch::zeros({1}, oi); s_ga = torch::zeros({1}, oi); s_gg = torch::zeros({1}, oi);
218	    }
219	    if (s_ws_floats < need) {
220	        s_ws = torch::empty({need}, torch::dtype(torch::kFloat32).device(params.device()));
221	        s_ws_floats = need;
222	    }
223	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
224	    float* loss_out = s_ws.data_ptr<float>() + (int64_t)n_sms * total + n_sms;
225	
226	    PersistentContext ctx{
227	        s_gn.data_ptr<int>(),
228	        reinterpret_cast<unsigned*>(s_ga.data_ptr<int>()),
229	        reinterpret_cast<unsigned*>(s_gg.data_ptr<int>()),
230	        ::sg::fused::sm90::kDecNumTensors, 0u};
231	
232	    FusedOptState st;
233	    float* m = state.data_ptr<float>();
234	    st.exp_avg = m; st.exp_avg_sq = m + total;
235	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
236	    st.eps = (float)eps; st.wd = (float)weight_decay;
237	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
238	
239	    DecoderTokenCtx tok;
240	    tok.tokens = tokens.data_ptr<int>();
241	    tok.targets = targets.data_ptr<int>();
242	    tok.B = B;
243	    tok.workspace = s_ws.data_ptr<float>();
244	    tok.loss_out = loss_out;
245	
246	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
247	    cudaError_t err = ::sg::fused::sm90::launch_fused_decoder_megakernel<OptId::AdamW>(
248	        ctx, params.data_ptr<float>(), tok, grad.data_ptr<float>(),
249	        (float)lr, (int)step, st, stream);
250	    TORCH_CHECK(err == cudaSuccess, "scalar megakernel launch failed: ", cudaGetErrorString(err));
251	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
252	
253	    auto loss_cpu = s_ws.slice(0, (int64_t)n_sms * total + n_sms, (int64_t)n_sms * total + n_sms + 1)
254	                        .to(torch::kCPU);
255	    return {loss_cpu, grad};
256	}
257	#endif  // SG_DEC_SCALAR_MEGAKERNEL
