259	#ifdef SG_DEC_PROFILE
260	// Diagnostic-only (SG_DEC_PROFILE; never shipped — the production _ops never sets
261	// this flag). Read + reset the per-phase clock64 maxima (cycles), 8 slots:
262	// [0]=P1 fwd, [1]=P1 bwd, [2]=B1 wait, [3]=P2 dW-GEMM, [4]=P2 grad-assembly,
263	// [5]=P3 opt tail, [6]=B2 wait, [7]=B0 wait. Call AFTER one tc_train_step; divide
264	// by the SM clock (~1.99 GHz boost on H100) to get ms, or read the RATIOS.
265	static std::vector<int64_t> tc_profile_read() {
266	    unsigned long long h[8] = {0, 0, 0, 0, 0, 0, 0, 0};
267	    cudaMemcpyFromSymbol(h, ::sg::fused::sm90::g_dec_prof_max, sizeof(h));
268	    unsigned long long z[8] = {0, 0, 0, 0, 0, 0, 0, 0};
269	    cudaMemcpyToSymbol(::sg::fused::sm90::g_dec_prof_max, z, sizeof(z));
270	    std::vector<int64_t> out(8);
271	    for (int i = 0; i < 8; ++i) out[i] = (int64_t)h[i];
272	    return out;
273	}
274	
275	#if SG_DEC_PROFILE_FWD_FINE
276	// Parallel reader for the FINE fwd/dX sub-phase counters (SG_DEC_PROFILE_FWD_FINE;
277	// only compiled when BOTH SG_DEC_PROFILE and SG_DEC_PROFILE_FWD_FINE are set).
278	// Read + reset g_dec_prof_fwd_fine [kDecFwdFineSlots] (cycles). Layout is
279	// [phase*kDecFwdFineSub + sub]: phase 0 = fwd ring, 1 = dX ring; sub ∈
280	// {0 ISSUE (cp.async LDGSTS issue), 1 WAIT (cp.async drain — the DRAIN/latency
281	// cost), 2 WGMMA (mma issue+commit+wait), 3 EPI (epilogue store), 4 BARRIER
282	// (fence+__syncthreads publish)}. Call AFTER one tc_train_step; divide by the SM
283	// clock (~1.98 GHz on H100) for ms, or read the RATIOS to localize whether P1_fwd
284	// / P1_bwd is DRAIN-bound (WAIT dominates → the deeper-ring lever helps) vs
285	// COMPUTE/EPILOGUE-bound (WGMMA/EPI dominate → it won't). Returns the flat slots
286	// + the (phases, sub) shape so the main loop can label them.
287	static std::vector<int64_t> tc_profile_read_fwd_fine() {
288	    constexpr int kSlots = ::sg::fused::sm90::dectc::kDecFwdFineSlots;
289	    unsigned long long h[kSlots];
290	    for (int i = 0; i < kSlots; ++i) h[i] = 0;
291	    cudaMemcpyFromSymbol(h, ::sg::fused::sm90::dectc::g_dec_prof_fwd_fine, sizeof(h));
292	    unsigned long long z[kSlots];
293	    for (int i = 0; i < kSlots; ++i) z[i] = 0;
294	    cudaMemcpyToSymbol(::sg::fused::sm90::dectc::g_dec_prof_fwd_fine, z, sizeof(z));
295	    std::vector<int64_t> out(kSlots);
296	    for (int i = 0; i < kSlots; ++i) out[i] = (int64_t)h[i];
297	    return out;
298	}
299	#endif
300	#endif
