302	PYBIND11_MODULE(TORCH_EXTENSION_NAME, mm) {
303	    mm.def("tc_train_step", &tc_train_step,
304	           "Fork-B tensor-core decoder fwd+bwd+AdamW step (in place); returns (loss, reduced grad)",
305	           pybind11::arg("params"), pybind11::arg("tokens"), pybind11::arg("targets"),
306	           pybind11::arg("state"), pybind11::arg("lr"), pybind11::arg("beta1"),
307	           pybind11::arg("beta2"), pybind11::arg("eps"), pybind11::arg("weight_decay"),
308	           pybind11::arg("bc1"), pybind11::arg("bc2"), pybind11::arg("step"),
309	           pybind11::arg("ncta_cap") = 0);
310	    mm.def("tc_dump_ff2_operands", &tc_dump_ff2_operands,
311	           "gate-only: dump the kernel's stored dY_ff2[L1], X_gact[L1] (fp32 CPU)");
312	#if SG_DEC_SCALAR_MEGAKERNEL
313	    mm.def("scalar_train_step", &scalar_train_step,
314	           "gate-only: SAME cell via the SCALAR launcher (back-to-back step-time mirror)",
315	           pybind11::arg("params"), pybind11::arg("tokens"), pybind11::arg("targets"),
316	           pybind11::arg("state"), pybind11::arg("lr"), pybind11::arg("beta1"),
317	           pybind11::arg("beta2"), pybind11::arg("eps"), pybind11::arg("weight_decay"),
318	           pybind11::arg("bc1"), pybind11::arg("bc2"), pybind11::arg("step"));
319	#endif
320	    mm.attr("TILE_M") = (int)::sg::fused::sm90::dectc::kTileM;
321	    mm.attr("TILE_N") = (int)SG_TUNED_TILE_N;
322	    mm.attr("TOTAL") = (int)kDecTotalElems;
323	    mm.attr("D") = (int)::sg::fused::sm90::SG_DEC_D;          // model width (128 prod / 1024 bench)
324	    mm.attr("DFF") = (int)::sg::fused::sm90::SG_DEC_DFF;
325	    mm.attr("LAYERS") = (int)::sg::fused::sm90::SG_DEC_LAYERS;
326	    mm.attr("SEQ") = (int)::sg::fused::sm90::SG_DEC_SEQ;
327	    mm.attr("VOCAB") = (int)::sg::fused::sm90::SG_DEC_VOCAB;
328	#ifdef SG_DEC_PROFILE
329	    mm.def("tc_profile_read", &tc_profile_read,
330	           "diagnostic-only: per-phase clock64 maxima "
331	           "[P1fwd,P1bwd,B1wait,P2dW,P2asm,P3opt,B2wait,B0wait] (cycles), resets after read");
332	    mm.attr("HAS_PROFILE") = true;
333	#if SG_DEC_PROFILE_FWD_FINE
334	    mm.def("tc_profile_read_fwd_fine", &tc_profile_read_fwd_fine,
335	           "diagnostic-only: FINE fwd/dX sub-phase clock64 maxima, flat "
336	           "[phase*FWD_FINE_SUB + sub]; phase 0=fwd ring, 1=dX ring; "
337	           "sub {0 ISSUE,1 WAIT(drain),2 WGMMA,3 EPI,4 BARRIER} (cycles), resets after read");
338	    mm.attr("HAS_FWD_FINE") = true;
339	    mm.attr("FWD_FINE_SUB") = (int)::sg::fused::sm90::dectc::kDecFwdFineSub;       // 5
340	    mm.attr("FWD_FINE_PHASES") = (int)::sg::fused::sm90::dectc::kDecFwdFinePhases; // 2
341	#else
342	    mm.attr("HAS_FWD_FINE") = false;
343	#endif
344	#else
345	    mm.attr("HAS_PROFILE") = false;
346	    mm.attr("HAS_FWD_FINE") = false;
347	#endif
348	    // Expose the fwd/dX deeper-ring knobs so the bench/main-loop can report them.
349	    mm.attr("FWD_PIPE") = (int)::sg::fused::sm90::dectc::kDecFwdPipe;
350	    mm.attr("FWD_STAGES") = (int)::sg::fused::sm90::dectc::kDecFwdStages;
351	}
